export type Row = Record<string, unknown>
type Field = { name: string; label: string; type?: string; required?: boolean; options?: { value: string; label: string }[]; hint?: string }

const today = new Date().toISOString().slice(0, 10)
const monthStart = `${today.slice(0, 7)}-01`

export function money(value: unknown, currency = 'INR') {
  const minor = Number(value || 0)
  return new Intl.NumberFormat('en-IN', { style: 'currency', currency, maximumFractionDigits: 2 }).format(minor / 100)
}
export function dateText(value: unknown) {
  if (!value) return '—'
  const date = new Date(String(value))
  return Number.isNaN(date.valueOf()) ? String(value) : new Intl.DateTimeFormat('en-IN', { dateStyle: 'medium' }).format(date)
}
function titleize(key: string) { return key.replace(/([A-Z])/g, ' $1').replace(/^./, c => c.toUpperCase()) }
function display(value: unknown, key = ''): ReactNode {
  if (value === null || value === undefined || value === '') return <span className="text-slate-400">—</span>
  if (key.toLowerCase().includes('minor') || key === 'amountMinor' || key === 'totalMinor') return money(value)
  if (key.toLowerCase().endsWith('at') || key === 'period' || key === 'startMonth' || key === 'drawMonth') return dateText(value)
  if (typeof value === 'boolean') return <Badge className={value ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}>{value ? 'Active' : 'Inactive'}</Badge>
  if (typeof value === 'object') return <span className="font-mono text-xs text-slate-500">{JSON.stringify(value)}</span>
  if (key.toLowerCase().includes('id') && String(value).length > 22) return <span title={String(value)}>{String(value).slice(0, 8)}…</span>
  return String(value)
}

function useLoad<T>(path: string | null, deps: unknown[] = []) {
  const [data, setData] = useState<T | null>(null)
  const [loading, setLoading] = useState(Boolean(path))
  const [error, setError] = useState('')
  const refresh = async () => {
    if (!path) return
    setLoading(true); setError('')
    try { setData(await api<T>(path)) } catch (err) { setError(err instanceof Error ? err.message : 'Could not load this data') }
    finally { setLoading(false) }
  }
  useEffect(() => { void refresh() // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [path, ...deps])
  return { data, loading, error, refresh, setData }
}

export function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
    <div>{eyebrow && <p className="mb-2 text-[10px] font-bold uppercase tracking-[.2em] text-indigo-600">{eyebrow}</p>}<h1 className="font-display text-2xl font-extrabold tracking-tight text-slate-950 sm:text-[30px]">{title}</h1>{description && <p className="mt-1.5 text-sm text-slate-500">{description}</p>}</div>{action}
  </div>
}

function Notice({ error, onRetry }: { error: string; onRetry?: () => void }) {
  if (!error) return null
  return <div className="mb-4 flex items-center justify-between gap-3 rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700"><span className="flex items-center gap-2"><CircleAlert size={16} />{error}</span>{onRetry && <Button variant="ghost" size="sm" onClick={onRetry}>Retry</Button>}</div>
}
function Loading() { return <div className="flex min-h-40 items-center justify-center text-sm text-slate-400"><LoaderCircle size={18} className="mr-2 animate-spin" />Loading records</div> }

export function DataTable({ rows, empty = 'No records yet', columns, actions }: { rows: Row[]; empty?: string; columns?: string[]; actions?: (row: Row) => ReactNode }) {
  const keys = columns || (rows[0] ? Object.keys(rows[0]).filter(k => !['userId', 'kycLast4', 'updatedAt', 'createdAt', '_optimistic'].includes(k)).slice(0, 6) : [])
  return <div className="overflow-x-auto"><table className="w-full min-w-170 text-left text-sm">
    <thead><tr className="border-b border-slate-100 text-[10px] font-bold uppercase tracking-[.12em] text-slate-400">{keys.map(key => <th className="px-5 py-3" key={key}>{titleize(key)}</th>)}{actions && <th className="px-5 py-3 text-right">Actions</th>}</tr></thead>
    <tbody className="divide-y divide-slate-100">{rows.map((row, i) => <tr key={String(row.id || i)} aria-busy={row._optimistic === true} className={`transition hover:bg-slate-50/80 ${row._optimistic === true ? 'opacity-65' : ''}`}>{keys.map((key,index) => <td key={key} className="max-w-64 px-5 py-3.5 text-slate-700">{display(row[key], key)}{row._optimistic === true && index===0 && <Badge className="ml-2 bg-indigo-50 text-indigo-700">Saving…</Badge>}</td>)}{actions && <td className="px-5 py-3 text-right">{row._optimistic === true?<span className="text-xs text-slate-400">Saving…</span>:actions(row)}</td>}</tr>)}</tbody>
  </table>{rows.length === 0 && <div className="px-5 py-14 text-center text-sm text-slate-400">{empty}</div>}</div>
}

function ModalForm({ title, fields, initial, onClose, onSubmit, busy }: { title: string; fields: Field[]; initial?: Row; onClose: () => void; onSubmit: (data: Row) => Promise<void>; busy: boolean }) {
  const [error, setError] = useState('')
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setError('')
    const form = new FormData(event.currentTarget); const value: Row = {}
    fields.forEach(field => { const raw = String(form.get(field.name) || ''); value[field.name] = field.type === 'number' ? Number(raw) : raw })
    try { await onSubmit(value) } catch (err) { setError(err instanceof Error ? err.message : 'Could not save the record') }
  }
  return <Modal ariaLabel={title} onClose={onClose} className="sm:max-w-xl">
    <div className="flex shrink-0 items-start justify-between border-b border-slate-100 px-6 py-5"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-indigo-600">Record details</p><h2 className="mt-1 font-display text-xl font-bold text-slate-950">{title}</h2></div><Button variant="ghost" size="icon" aria-label="Close form" onClick={onClose}><X size={18} /></Button></div>
    <form onSubmit={submit} className="flex min-h-0 flex-1 flex-col"><div className="min-h-0 flex-1 space-y-4 overflow-y-auto px-6 py-5"><Notice error={error} />{fields.map(field => <label className="block" key={field.name}><span className="mb-1.5 block text-xs font-semibold text-slate-700">{field.label}{field.required && <span className="text-rose-500"> *</span>}</span>{field.options ? <Select name={field.name} required={field.required} defaultValue={String(initial?.[field.name] || '')}><option value="">Choose {field.label.toLowerCase()}</option>{field.options.map(option => <option value={option.value} key={option.value}>{option.label}</option>)}</Select> : <Input name={field.name} required={field.required} type={field.type || 'text'} min={field.type === 'number' ? 0 : undefined} step={field.name.toLowerCase().includes('amount') || field.name.toLowerCase().includes('contribution') ? 1 : undefined} defaultValue={String(initial?.[field.name] ?? '')} placeholder={field.hint || field.label} />}</label>)}</div><div className="flex shrink-0 justify-end gap-2 border-t border-slate-100 bg-white px-6 py-4"><Button type="button" variant="outline" onClick={onClose}>Cancel</Button><Button disabled={busy}>{busy ? 'Saving…' : 'Save record'}</Button></div></form>
  </Modal>
}

